-- v134: 数学[职高] (subject_id=22) L4知识节点内容填充 Batch2
-- 覆盖模块: 数列 / 平面向量 / 立体几何 / 平面解析几何
-- 共18个L4节点

-- ============================================================
-- 数列: 数列的概念 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='数列的概念' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】数列是按一定次序排列的一列数，可看作定义在正整数集上的函数。\n\n【具体说明】\n① 数列是按一定顺序排列的一列数，如 1, 3, 5, 7, ... 每一项都有确定的位置。\n② 按项数可分为有穷数列和无穷数列；按项的大小变化可分为递增数列、递减数列、常数列、摆动数列。\n③ 通项公式 a_n = f(n) 表示第 n 项与序号 n 的关系，是数列的核心表示方式。\n\n【常见错误】\n1. 混淆数列与数集 → 数列有序可重复，数集无序且元素互异。\n2. 认为所有数列都有通项公式 → 并非所有数列都能写出通项公式，如质数数列。\n\n【考试方向】\n给出数列前几项，求通项公式 a_n；判断给定数列的类型（递增/递减/摆动）。' WHERE parent_id=@l3 AND name='数列的定义与分类';

-- ============================================================
-- 数列: 等差数列 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='等差数列' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】等差数列的通项公式为 a_n = a_1 + (n-1)d，其中 d 为公差，n 为项数。\n\n【具体说明】\n① 定义：a_{n+1} - a_n = d (常数)，称 {a_n} 为等差数列，d 为公差。\n② 通项公式：a_n = a_1 + (n-1)d = a_m + (n-m)d，即从首项起每次加一个公差。\n③ 已知任意两项可求公差：d = (a_n - a_m)/(n - m)，例如 a_3=7, a_8=22 得 d=3。\n\n【常见错误】\n1. 将 a_n = a_1 + (n-1)d 写成 a_1+nd → 从 a_1 到 a_n 加 (n-1) 个 d。\n2. 公差 d 为负时仍按正数算 → d 可取任意实数，负公差表示数列递减。\n\n【考试方向】\n已知 a_1 和 d 求第 n 项；已知两项求公差及通项公式；判断某数是否为数列中的项。' WHERE parent_id=@l3 AND name='等差数列通项公式';

UPDATE knowledge_nodes SET content='【一句话定义】等差数列前 n 项和公式：S_n = n(a_1+a_n)/2 = na_1 + n(n-1)d/2。\n\n【具体说明】\n① 推导方法——倒序相加：S_n = a_1+a_2+...+a_n，倒序 S_n = a_n+...+a_1，两式相加得 2S_n = n(a_1+a_n)。\n② 第二形式代入 a_n = a_1+(n-1)d 得 S_n = na_1 + n(n-1)d/2，已知 a_1 和 d 时方便使用。\n③ S_n 是 n 的二次函数 (d≠0 时)，图像为过原点的抛物线上的离散整数点。\n\n【常见错误】\n1. 忘记除以 2 → S_n = n(a_1+a_n)/2，分子 n(a_1+a_n) 后必须除 2。\n2. 将 n(n-1)d/2 误写为 n(n+1)d/2 → n(n-1) 不是 n(n+1)。\n\n【考试方向】\n已知 a_1, d, n 求 S_n；已知 S_n 及部分条件求 n 或 d；通项与求和公式联合考查（解答题常考）。' WHERE parent_id=@l3 AND name='等差数列前n项和';

-- ============================================================
-- 数列: 等比数列 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='等比数列' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】等比数列的通项公式为 a_n = a_1·q^{n-1}，其中 q 为公比 (q≠0)，n 为项数。\n\n【具体说明】\n① 定义：a_{n+1}/a_n = q (q≠0，常数)，称 {a_n} 为等比数列，q 为公比。\n② 通项公式：a_n = a_1·q^{n-1} = a_m·q^{n-m}，体现了等比数列的指数增长特性。\n③ 等比中项：若 a, G, b 成等比数列，则 G² = ab (G = ±√(ab))，符号取决于各项。\n\n【常见错误】\n1. 混淆等差与等比通项形式 → 等差是加 (n-1)d，等比是乘以 q^{n-1}。\n2. 公比 q 可能为负数而忽略 → q<0 时数列正负交替，如 a_1=1, q=-2 得 1,-2,4,-8,...。\n\n【考试方向】\n已知 a_1 和 q 求任意项；已知两项求公比和通项公式；判断某数是否为等比数列中的项。' WHERE parent_id=@l3 AND name='等比数列通项公式';

UPDATE knowledge_nodes SET content='【一句话定义】等比数列前 n 项和：q≠1 时 S_n = a_1(1-qⁿ)/(1-q)；q=1 时 S_n = na_1。\n\n【具体说明】\n① 推导方法——错位相减：写 S_n = a_1+a_1q+...+a_1q^{n-1}，两边乘 q 得 qS_n，两式相减消去中间项解出 S_n。\n② 等价形式：S_n = a_1(1-qⁿ)/(1-q) = a_1(qⁿ-1)/(q-1)，选择便于计算的版本。\n③ 使用公式前必须先判断 q 是否等于 1，q=1 时所有项相等，直接 S_n = na_1。\n\n【常见错误】\n1. 忘记讨论 q=1 的情况 → 必须分 q=1 和 q≠1 两种情形处理。\n2. (1-qⁿ) 与 (qⁿ-1) 对应分母符号弄反 → 选一个形式记住即可。\n\n【考试方向】\n已知 a_1, q, n 求 S_n；已知 S_n 和 a_1 求 q 或 n；通项与求和联合考查（常以解答题出现）。' WHERE parent_id=@l3 AND name='等比数列前n项和';

-- ============================================================
-- 数列: 数列求和 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='数列求和' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】分组求和法是将数列拆分为若干可分别求和的子数列（如等差部分+等比部分），分别求和后合并。\n\n【具体说明】\n① 适用类型：通项由等差±等比或等差±常数等组合而成，如 a_n = 2n + 3ⁿ。\n② 方法：将 a_n 拆成 b_n ± c_n，则 S_n = Σb_n ± Σc_n，各部分用各自的求和公式。\n③ 典型例题：求 a_n = n + 2ⁿ 的前 n 项和，S_n = n(n+1)/2 + 2(2ⁿ-1)。\n\n【常见错误】\n1. 分组时某项被重复计算或遗漏 → 写出前几项验证分组是否正确。\n2. 各组用错求和公式 → 先判断每组是等差还是等比，再选对公式。\n\n【考试方向】\n求如 a_n = 2n-1 + (1/2)ⁿ 的数列前 n 项和；常以解答题出现，与等差等比知识综合。' WHERE parent_id=@l3 AND name='分组求和法';

UPDATE knowledge_nodes SET content='【一句话定义】裂项相消法是将通项拆成两项之差，使得求和时相邻项相互抵消，仅剩首尾若干项。\n\n【具体说明】\n① 最常见的裂项：1/[n(n+1)] = 1/n - 1/(n+1)；1/[n(n+k)] = (1/k)(1/n - 1/(n+k))。\n② 求和演示：a_n = 1/n - 1/(n+1)，S_n = (1-1/2)+(1/2-1/3)+...+(1/n-1/(n+1)) = 1 - 1/(n+1)。\n③ 分母含根式也可裂项：1/(√a+√b) = (√a-√b)/(a-b)，利用有理化变形。\n\n【常见错误】\n1. 裂项形式写好后不验证 → 将裂项结果通分还原，检查是否等于原通项。\n2. 中间项抵消不彻底 → 写出前 3 项和最后 2 项，确认抵消规律。\n\n【考试方向】\n求 Σ1/[n(n+1)] 或 Σ1/[(2n-1)(2n+1)] 的前 n 项和；以化简求值或求和题为主。' WHERE parent_id=@l3 AND name='裂项相消法';

-- ============================================================
-- 平面向量: 向量的概念与线性运算 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的概念与线性运算' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】向量是既有大小又有方向的量，用有向线段表示（如 ā 或 AB→），其大小称为模 |ā|。\n\n【具体说明】\n① 向量三要素：大小（模）、方向、作用点（自由向量可以平移，位置不影响相等判定）。\n② 表示方式：几何上用有向线段，代数上用坐标 (x,y)；印刷体加粗（a），手写加箭头（ā）。\n③ 特殊向量：零向量 0̄（模为 0，方向任意），单位向量（模为 1，常用于表示方向）。\n\n【常见错误】\n1. 认为向量由其起点和终点唯一确定 → 向量可平移，大小方向相同即相等。\n2. 零向量的方向说成"没有方向" → 零向量的方向是"任意的"，不是没有。\n\n【考试方向】\n判断两个向量是否相等（同向且等长）；区分向量与数量；零向量和单位向量的概念辨析。' WHERE parent_id=@l3 AND name='向量的定义与表示';

UPDATE knowledge_nodes SET content='【一句话定义】向量的线性运算包括加法（三角形/平行四边形法则）、减法（加相反向量）和数乘 λā。\n\n【具体说明】\n① 加法：三角形法则（首尾相接，ā 终点连 b̄ 起点）和平行四边形法则（同一起点，对角线为和）。\n② 减法：ā - b̄ = ā + (-b̄)，几何意义是由 b̄ 终点指向 ā 终点的向量。\n③ 数乘 λā：|λā| = |λ|·|ā|；λ>0 同向，λ<0 反向，λ=0 得零向量；满足分配律。\n\n【常见错误】\n1. 三角形法则方向画反 → ā+b̄：ā 的终点接 b̄ 的起点，结果从 ā 起点到 b̄ 终点。\n2. 数乘后将结果写成数值 → λā 仍是向量，必须保留向量符号 ā。\n\n【考试方向】\n利用三角形法则化简向量表达式（如 AB→+BC→=AC→）；判断两向量是否共线；含参数的向量运算。' WHERE parent_id=@l3 AND name='向量的加减法与数乘';

-- ============================================================
-- 平面向量: 向量的数量积 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的数量积' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】向量 ā 与 b̄ 的数量积定义为 ā·b̄ = |ā||b̄|cosθ，结果是一个数量，不是向量。\n\n【具体说明】\n① 几何定义：ā·b̄ = |ā|·|b̄|·cosθ，θ 为两向量夹角（0 ≤ θ ≤ π）。\n② 坐标公式：若 ā=(x₁,y₁), b̄=(x₂,y₂)，则 ā·b̄ = x₁x₂ + y₁y₂。\n③ 核心性质：ā⊥b̄ ⇔ ā·b̄=0；ā·ā=|ā|²；cosθ = (ā·b̄)/(|ā||b̄|)。\n\n【常见错误】\n1. 误以为 ā·b̄ 结果为向量 → 数量积结果是数量（点乘得数），区别于向量积。\n2. 求夹角时忘记除以模的乘积 → cosθ = ā·b̄/(|ā||b̄|)，必须除以两个模的积。\n\n【考试方向】\n已知坐标求数量积；利用数量积求夹角或证明垂直；结合 |ā|²=ā·ā 求模长。' WHERE parent_id=@l3 AND name='数量积的定义与计算';

-- ============================================================
-- 平面向量: 向量的坐标运算 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的坐标运算' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】平面向量可用有序实数对 (x,y) 表示，向量运算转化为对应坐标的代数运算。\n\n【具体说明】\n① 向量坐标：若 A(x₁,y₁), B(x₂,y₂)，则 AB→ = (x₂-x₁, y₂-y₁)，即终点坐标减起点坐标。\n② 运算法则：ā±b̄ = (x₁±x₂, y₁±y₂)；λā = (λx₁, λy₁)；相等向量对应坐标相等。\n③ 向量的模：|ā| = √(x₁² + y₁²)，即坐标平方和的算术平方根。\n\n【常见错误】\n1. 终点减起点顺序颠倒 → AB→ = B坐标 - A坐标，不是 A-B。\n2. 模公式忘记开平方根 → |ā| = √(x²+y²)，不是 x²+y²。\n\n【考试方向】\n已知点坐标求向量坐标（始点终点）；利用坐标进行加、减、数乘运算；求向量的模长。' WHERE parent_id=@l3 AND name='向量的坐标表示';

UPDATE knowledge_nodes SET content='【一句话定义】利用向量坐标可判定共线、垂直，求夹角、距离，将几何问题代数化。\n\n【具体说明】\n① 共线判定：ā∥b̄ ⇔ x₁y₂ - x₂y₁ = 0，即对应坐标成比例（叉积为零）。\n② 垂直判定：ā⊥b̄ ⇔ x₁x₂ + y₁y₂ = 0（点积为零）。\n③ 夹角公式：cosθ = (x₁x₂+y₁y₂)/[√(x₁²+y₁²)·√(x₂²+y₂²)]，求两向量夹角的余弦值。\n\n【常见错误】\n1. 共线与垂直的坐标条件记反 → 共线看叉积（x₁y₂-x₂y₁），垂直看点积（x₁x₂+y₁y₂）。\n2. 用模长公式时只加坐标忘记平方 → 模是 √(x²+y²)，不是 x+y。\n\n【考试方向】\n判断三点共线或两向量平行/垂直；求两向量夹角；利用向量坐标法解决平面几何证明题。' WHERE parent_id=@l3 AND name='坐标运算的应用';

-- ============================================================
-- 立体几何: 空间几何体 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='空间几何体' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】几何体的表面积是其所有面的面积之和（侧面积+底面积），不同几何体有对应的计算公式。\n\n【具体说明】\n① 圆柱：S = 2πr² + 2πrh = 2πr(r+h)，其中 r 为底面半径，h 为高。\n② 圆锥：S = πr² + πrl = πr(r+l)，其中 l 为母线长（l = √(r²+h²)）。\n③ 球：S = 4πR²，其中 R 为球的半径。\n\n【常见错误】\n1. 圆锥侧面积 πrl 误记为 2πrl → 圆柱侧面积是 2πrh，圆锥无系数 2。\n2. 混淆柱体与锥体的面数 → 棱柱有 2 个底面+侧面，棱锥只有 1 个底面+侧面。\n\n【考试方向】\n给定几何体尺寸直接套公式求表面积；结合实际情境（如无盖容器、半圆柱等）求部分表面积。' WHERE parent_id=@l3 AND name='常见几何体的表面积';

UPDATE knowledge_nodes SET content='【一句话定义】几何体的体积是其所占空间的大小，柱体 V=S_底·h，锥体 V=(1/3)S_底·h，球体 V=(4/3)πR³。\n\n【具体说明】\n① 柱体：V = S_底 × h；圆柱 V = πr²h；棱柱 V = S_底·h。\n② 锥体：V = (1/3)S_底 × h；圆锥 V = (1/3)πr²h；等底等高的锥体体积是柱体的 1/3。\n③ 球体：V = (4/3)πR³，与表面积公式区分（表面积是 4πR²）。\n\n【常见错误】\n1. 锥体体积漏写系数 1/3 → 同底等高的锥体体积是柱体的三分之一。\n2. 球的体积与表面积公式混淆 → V=4πR³/3，S=4πR²，相差一个 3 和一次幂。\n\n【考试方向】\n直接套用公式求体积；已知体积反求参数（半径或高）；组合体（柱+锥+球）的体积计算。' WHERE parent_id=@l3 AND name='常见几何体的体积';

-- ============================================================
-- 立体几何: 点线面的位置关系 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='点线面的位置关系' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】线面平行：平面外一直线与平面内一直线平行则线面平行；线面垂直：直线垂直于平面内两条相交直线则线面垂直。\n\n【具体说明】\n① 线面平行判定：l ⊄ α, m ⊂ α, l∥m ⇒ l∥α（线线平行推出线面平行）。\n② 线面垂直判定：l⊥a, l⊥b, a∩b=P, a,b⊂α ⇒ l⊥α（线线垂直推出线面垂直，需两条相交直线）。\n③ 线面垂直性质：垂直于同一平面的两直线互相平行（a⊥α, b⊥α ⇒ a∥b）。\n\n【常见错误】\n1. 线面垂直只用平面内一条直线判定 → 必须两条相交直线，一条不成立。\n2. 用直线与平面平行代替直线在平面外 → 线面平行的前提是直线不在平面内。\n\n【考试方向】\n长方体或棱柱棱锥中判断/证明线面平行或垂直；以几何证明题为主，常结合位置关系综合考查。' WHERE parent_id=@l3 AND name='线面平行与垂直的判定';

UPDATE knowledge_nodes SET content='【一句话定义】面面平行：一平面内两条相交直线分别平行于另一平面则两面平行；面面垂直：一平面包含另一平面的垂线则两面垂直。\n\n【具体说明】\n① 面面平行判定：a,b⊂α, a∩b=P, a∥β, b∥β ⇒ α∥β（线面平行推面面平行，需两相交线）。\n② 面面垂直判定：l⊂α, l⊥β ⇒ α⊥β（线面垂直推面面垂直）。\n③ 面面垂直性质：两平面垂直时，一平面内垂直于交线的直线垂直于另一平面。\n\n【常见错误】\n1. 面面平行只用一条平行线判定 → 必须两条相交直线分别平行于另一平面。\n2. 面面垂直用线面平行代替线面垂直 → 必须线面垂直才能推出面面垂直。\n\n【考试方向】\n结合长方体或棱锥判断/证明面面平行或垂直；空间中位置关系的综合推理题（常为中档题）。' WHERE parent_id=@l3 AND name='面面平行与垂直的判定';

-- ============================================================
-- 平面解析几何: 直线方程 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='直线方程' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】直线的倾斜角 α 是直线向上方向与 x 轴正方向的夹角 (0°≤α<180°)；斜率 k=tanα (α≠90°)。\n\n【具体说明】\n① 倾斜角范围：α ∈ [0, π)，即 0°≤α<180°；α=0° 时直线与 x 轴平行；α=90° 时直线与 x 轴垂直（斜率不存在）。\n② 斜率公式：过 P₁(x₁,y₁) 和 P₂(x₂,y₂) 的直线，k = (y₂-y₁)/(x₂-x₁) (x₁≠x₂)。\n③ k>0 则 α 为锐角；k<0 则 α 为钝角；k=0 则 α=0°；k 不存在则 α=90°。\n\n【常见错误】\n1. 斜率公式分子分母颠倒 → k = (y₂-y₁)/(x₂-x₁)，纵差除以横差。\n2. 认为所有直线都有斜率 → 垂直于 x 轴的直线（x=a）斜率不存在。\n\n【考试方向】\n已知两点求斜率和倾斜角；已知斜率和一点求倾斜角；判断斜率大小与直线陡峭程度的关系。' WHERE parent_id=@l3 AND name='直线的倾斜角与斜率';

UPDATE knowledge_nodes SET content='【一句话定义】直线方程有五种形式：点斜式、斜截式、两点式、截距式、一般式，适用于不同的已知条件。\n\n【具体说明】\n① 点斜式：y-y₀=k(x-x₀)，已知一点和斜率。\n② 斜截式：y=kx+b，已知斜率和 y 轴截距 b。\n③ 两点式：(y-y₁)/(y₂-y₁)=(x-x₁)/(x₂-x₁)，已知两点 (x₁≠x₂, y₁≠y₂)。\n④ 截距式：x/a + y/b = 1 (a,b≠0)，已知 x 轴截距 a 和 y 轴截距 b。\n⑤ 一般式：Ax+By+C=0 (A,B 不全为 0)，最通用的形式，斜率 k=-A/B (B≠0)。\n\n【常见错误】\n1. 点斜式中 x-x₀ 和 y-y₀ 位置写反 → y-y₀ = k(x-x₀)，左边是纵差，右边是斜率乘横差。\n2. 截距式 a,b 与斜截式的 k,b 混淆 → 截距式用 x/a+y/b=1，a 是 x 轴截距。\n\n【考试方向】\n根据条件选合适形式写出直线方程；五种形式的互化；求直线与坐标轴的交点和截距。' WHERE parent_id=@l3 AND name='直线的五种方程形式';

-- ============================================================
-- 平面解析几何: 圆的方程 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='圆的方程' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】圆心为 (a,b)、半径为 r 的圆的标准方程为 (x-a)²+(y-b)²=r² (r>0)。\n\n【具体说明】\n① 标准形式：(x-a)²+(y-b)²=r²，圆心 (a,b)，半径 r。\n② 特例：圆心在原点时方程为 x²+y²=r²，结构最简单。\n③ 已知圆心和圆上一点可直接得半径 r=√((x₀-a)²+(y₀-b)²)，代入标准方程即可。\n\n【常见错误】\n1. 方程右边写成 r 而非 r² → 标准方程右边必须是半径的平方 r²。\n2. 圆心坐标符号搞反 → (x+3)²+(y-2)²=4 的圆心是 (-3,2)，注意 x-a 中 a=-3。\n\n【考试方向】\n已知圆心和半径直接写标准方程；已知圆心和圆上一点求方程；由一般式配方化为标准式找圆心和半径。' WHERE parent_id=@l3 AND name='圆的标准方程';

UPDATE knowledge_nodes SET content='【一句话定义】圆的一般方程为 x²+y²+Dx+Ey+F=0，D²+E²-4F>0 时表示圆，圆心 (-D/2,-E/2)，半径 r=√(D²+E²-4F)/2。\n\n【具体说明】\n① 一般式配方：(x+D/2)²+(y+E/2)²=(D²+E²-4F)/4，可见圆心 (-D/2,-E/2)，r²=(D²+E²-4F)/4。\n② 判别条件：D²+E²-4F>0→圆；=0→点圆；<0→无轨迹（不表示任何图形）。\n③ 特征：x² 和 y² 系数相等（通常为 1），且无 xy 交叉项。\n\n【常见错误】\n1. 配方后忘记右边除以 4 → r²=(D²+E²-4F)/4，开方得 r=√(D²+E²-4F)/2。\n2. D²+E²-4F≤0 时仍当作圆处理 → 必须先检查判别式是否大于零。\n\n【考试方向】\n一般式配方求圆心坐标和半径；判断给定二元二次方程是否表示圆；标准式与一般式互化。' WHERE parent_id=@l3 AND name='圆的一般方程';

-- ============================================================
-- 平面解析几何: 直线与圆的位置关系 (parent)
-- ============================================================

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='直线与圆的位置关系' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content='【一句话定义】直线与圆的位置关系由圆心到直线的距离 d 与半径 r 比较判定：d<r 相交，d=r 相切，d>r 相离。\n\n【具体说明】\n① 距离公式：圆心 (a,b) 到直线 Ax+By+C=0 的距离 d = |Aa+Bb+C|/√(A²+B²)。\n② 判定结果：d<r⇔相交（2个交点）；d=r⇔相切（1个切点）；d>r⇔相离（0个交点）。\n③ 代数法：联立直线与圆方程组，用判别式 Δ 判断：Δ>0相交，Δ=0相切，Δ<0相离。\n\n【常见错误】\n1. 距离公式分子忘记加绝对值 → d=|Aa+Bb+C|/√(A²+B²)，距离必须非负。\n2. 距离法与判别式法结论不一致 → 两种方法应互相验证，结果为等价。\n\n【考试方向】\n判断给定直线与圆的位置关系；已知位置关系求参数的取值范围；求切线方程。' WHERE parent_id=@l3 AND name='直线与圆的位置关系判断';

UPDATE knowledge_nodes SET content='【一句话定义】弦长公式 l=2√(r²-d²)（d 为圆心到直线距离）；过圆上一点的切线可用替换法则直接写出。\n\n【具体说明】\n① 弦长：由勾股定理，半径 r、半弦长 l/2、弦心距 d 满足 (l/2)²+d²=r²，故 l=2√(r²-d²)。\n② 切线：过圆 (x-a)²+(y-b)²=r² 上一点 (x₀,y₀) 的切线为 (x₀-a)(x-a)+(y₀-b)(y-b)=r²。\n③ 过圆外一点的切线有两条，可设斜率 k，利用圆心到切线距离等于半径 r 解出 k。\n\n【常见错误】\n1. 弦长公式漏乘 2 → l=2√(r²-d²)，先算半弦长再乘 2。\n2. 求切线时忽略斜率不存在的情况 → 竖直线也可能是切线，需单独讨论。\n\n【考试方向】\n已知直线与圆相交求弦长；过圆上一点或圆外一点求切线方程；与圆有关的最值问题（最长弦/最短弦）。' WHERE parent_id=@l3 AND name='弦长与切线问题';

